gabV(){return"\u041c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u043e\u0432. \u0421\u0443\u043c\u043c\u044b \u0432 \u0444\u0438\u0448\u043a\u0430\u0445 \u043f\u0430\u0440\u0442\u0438\u0438."},
ga9X(){return"\u0412\u0441\u0435 \u043f\u0440\u0438 \u0441\u0432\u043e\u0438\u0445."},
gaaW(){return"+ \u0414\u043e\u043a\u0443\u043f\u043a\u0430 \u0438\u0433\u0440\u043e\u043a\u0443"},
Qs(a){return"\u0414\u043e\u043a\u0443\u043f\u043a\u0430 \xb7 "+a},
gaao(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0443, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u0448\u0430\u0433\u0438 \u0438\u043b\u0438 \u0438\u0441\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u043f\u043e\u0431\u0435\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u2014 \u0441\u0442\u0435\u043a\u0438 \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f."},
gabL(){return"\u0432\u0441\u0435 \u0441\u0431\u0440\u043e\u0441\u0438\u043b\u0438"},
gabN(){return"\u0432\u0441\u043a\u0440\u044b\u0442\u0438\u0435"},
gQD(){return"\u0441\u0442\u0440\u0430\u0434\u0434\u043b"},
gQC(){return"\u0431\u043e\u043c\u0431-\u043f\u043e\u0442"},
abM(a){return"\u043f\u0440\u043e\u043a\u0440\u0443\u0442\u043a\u0430 "+a},
gaal(){return"\u0428\u0430\u0433\u0438 \u0440\u0430\u0437\u0434\u0430\u0447\u0438"},
gQk(){return"\u0418\u0441\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u043f\u043e\u0431\u0435\u0434\u0438\u0442\u0435\u043b\u0435\u0439"},
FX(a,b,c){return a+": "+b+" "+c},
gaaK(){return"SB"},
gaaI(){return"BB"},
gaaL(){return"\u0441\u0442\u0440\u0430\u0434\u0434\u043b"},
gaaJ(){return"\u0431\u043e\u043c\u0431-\u043f\u043e\u0442"},
a9U(a){return a+": \u043f\u0430\u0441"},
