a9S(a){return a+": \u043a\u043e\u043b\u043b"},
a9V(a,b){return a+": \u0434\u043e "+b},
gabW(){return"\u0412\u044b\u043f\u043b\u0430\u0442\u044b"},
gQg(){return"\u0421\u0432\u043e\u0451\u2026"},
gQi(){return"\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0447\u0438\u0441\u043b\u043e"},
Ql(a,b){return a+": \u0441\u0442\u0435\u043a "+b},
gafd(){return"\u041e\u0441\u043d\u043e\u0432\u044b"},
gafe(){return"\u0421\u043f\u043e\u0440\u043d\u044b\u0435 \u043c\u043e\u043c\u0435\u043d\u0442\u044b"},
gaff(){return"\u0418\u0433\u0440\u0430:"},
gaft(){return"\u0421\u0442\u0430\u0440\u0448\u0438\u043d\u0441\u0442\u0432\u043e \u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0446\u0438\u0439"},
gafl(){return"\u041b\u043e\u0443: 5 \u0440\u0430\u0437\u043d\u044b\u0445 \u043a\u0430\u0440\u0442 \u043d\u0435 \u0432\u044b\u0448\u0435 8, \u0442\u0443\u0437 \u043c\u043b\u0430\u0434\u0448\u0438\u0439; \u043b\u0443\u0447\u0448\u0438\u0439 \u2014 A-2-3-4-5."},
gafo(){return"\u0412\u0435\u0440\u0445: 66 \u2014 1 \u2026 AA \u2014 9; 222 \u2014 10 \u2026 AAA \u2014 22."},
gafv(){return"\u0421\u0435\u0440."},
gafu(){return"\u041d\u0438\u0437"},
ga7c(){return"A K Q J 10 \u043e\u0434\u043d\u043e\u0439 \u043c\u0430\u0441\u0442\u0438"},
